// The plan overlay's model (req #3762): a decision record — the engine's, or
// the prediction made from the derived block — mapped to the badges on the
// epic cards, the cut line, the limits and the machine of every launch.
//
// Every record here is decide()'s (planOverlayFixture.json, generated by
// scripts/swarm/engine2/overlay_fixture.py), so the badges are tested against
// what the engine publishes, and against the engine view's own numbering
// (`recordView`) — the acceptance is that the two pages agree exactly.

import { describe, expect, it } from 'vitest';

import fixture from './planOverlayFixture.json';
import { recordView } from '../engineModel';
import {
    SOURCE_ENGINE, SOURCE_PREDICTED, leadMachineOf, planOverlay, positionsText, predictionCapacity,
    predictionClaims,
} from '../engineOverlay';
import { predictRecord } from '../enginePredict';
import { PLAIN_WORDS } from '../engineVocabulary';

const action = (id) => fixture.actions.find((a) => a.action === id);
const stateOf = (id, index) => action(id).states[index];
const recordOf = (id, index) => stateOf(id, index).record_row.record;
const engineOverlayOf = (id, index, liveClaims = []) => planOverlay(recordOf(id, index), {
    source: SOURCE_ENGINE, payload: stateOf(id, index).payload, liveClaims });

function predictedOverlayOf(id, index) {
    const state = stateOf(id, index);
    const claims = predictionClaims({ claimRows: state.claims, pipelineId: state.payload.pipeline.id,
        machineId: fixture.this_machine });
    const capacity = { ceiling: state.ceiling, live: state.live_sessions, reserved_elsewhere: 0 };
    const record = predictRecord(state.payload, capacity, claims, { now: state.clock });
    return planOverlay(record, { source: SOURCE_PREDICTED, payload: state.payload,
        liveClaims: claims.live.filter((c) => !c.stale) });
}

describe('positionsText', () => {
    it('reads queue positions the way a badge shows them', () => {
        expect(positionsText([1])).toBe('1');
        expect(positionsText([2, 3])).toBe('2,3');
        expect(positionsText([4, 5, 6])).toBe('4–6');
        expect(positionsText([5, 1, 2, 3])).toBe('1–3,5');
        expect(positionsText([])).toBe('');
    });
});

describe('an engine record → badges and the cut', () => {
    it('numbers each epic by its launches\' queue positions, as the engine view does', () => {
        const overlay = engineOverlayOf('A16', 0);
        const view = recordView(recordOf('A16', 0));
        // The engine view's numbering, item by item.
        expect(overlay.queue.map((q) => [q.position, q.epicId, q.requirementId, q.code]))
            .toEqual(view.queue.map((q) => [q.position, q.epicId, q.requirementId, q.code]));
        expect(overlay.badges.get(101)).toMatchObject({ text: '1', code: 'ADMITTED', held: false,
            belowCut: false, cutBefore: false });
        expect(overlay.badges.get(103)).toMatchObject({ text: '2', code: 'ADMITTED', held: false });
        expect(overlay.badges.get(102)).toMatchObject({ text: '3', code: 'DEP_PRIORITY', held: true,
            belowCut: true, cutBefore: true, words: PLAIN_WORDS.DEP_PRIORITY,
            detail: 'waiting on epic Epic 101' });
        expect(overlay.cut).toBe(2);
        expect(overlay.cutShown).toBe(true);
        expect(overlay.limits).toEqual({ ceiling: 2, live: 0, reserved: 0, free: 2 });
        expect(overlay.source).toBe(SOURCE_ENGINE);
        expect(overlay.seq).toBe(1);
    });

    it('shows an epic held before the queue by its hold\'s label, in the plain words', () => {
        const overlay = engineOverlayOf('A8', 0);
        const barrier = overlay.badges.get(102);
        expect(barrier).toMatchObject({ code: 'BARRIER', text: 'Barrier', held: true, positions: [],
            words: PLAIN_WORDS.BARRIER, detail: 'held by barrier epic Epic 101' });
        expect(overlay.badges.get(101)).toMatchObject({ code: 'ADMITTED', text: '1' });
        expect(overlay.cutShown).toBe(false);
    });

    it('every hold the plan-overlay actions produce is a badge with its plain words', () => {
        const seen = new Set();
        for (const a of fixture.actions) {
            a.states.forEach((_, i) => {
                const overlay = engineOverlayOf(a.action, i);
                for (const badge of overlay.badges.values()) {
                    seen.add(badge.code);
                    expect(badge.words).toBe(PLAIN_WORDS[badge.code]);
                    expect(badge.text).not.toBe('');
                }
            });
        }
        for (const code of ['BARRIER', 'DEP_PRIORITY', 'MANUAL', 'NOT_BEFORE', 'SERIAL_TURN',
            'MACHINE_PIN', 'NO_WORK', 'CAPACITY', 'IN_FLIGHT', 'ADMITTED']) {
            expect(seen, code).toContain(code);
        }
    });

    it('moves the cut by exactly the slots freed (A18)', () => {
        const full = engineOverlayOf('A18', 0);
        const freed = engineOverlayOf('A18', 1);
        expect(full.cut).toBe(0);
        expect(full.limits.free).toBe(0);
        expect(freed.cut).toBe(2);
        expect(freed.limits.free).toBe(2);
        expect(freed.badges.get(101)).toMatchObject({ text: '1–4', code: 'ADMITTED', belowCut: false,
            cutBefore: true });
    });
});

describe('the machine each launch runs on', () => {
    it('a pinned launch runs on its pin; Any work on the lead (A12, lead on machine 1)', () => {
        const overlay = engineOverlayOf('A12', 1, [
            { id: 1, pipeline_fk: 900, initiative_fk: null, machine_fk: 1 },
            { id: 2, pipeline_fk: 900, initiative_fk: null, machine_fk: 2 },
        ]);
        const byReq = new Map(overlay.queue.map((q) => [q.requirementId, q]));
        expect(byReq.get(3001)).toMatchObject({ code: 'ADMITTED', machineId: 1 });
        expect(byReq.get(3002)).toMatchObject({ code: 'MACHINE_PIN', machineId: 2 });
        expect(byReq.get(3003)).toMatchObject({ code: 'ADMITTED', machineId: 1 });
    });

    it('a subscriber\'s Any work is the lead machine\'s (A12, subscriber on machine 2)', () => {
        const overlay = engineOverlayOf('A12', 0, [
            { id: 1, pipeline_fk: 900, initiative_fk: null, machine_fk: 1 },
            { id: 2, pipeline_fk: 900, initiative_fk: null, machine_fk: 2 },
        ]);
        const byReq = new Map(overlay.queue.map((q) => [q.requirementId, q]));
        expect(byReq.get(3001)).toMatchObject({ code: 'MACHINE_PIN', machineId: 1 });
        expect(byReq.get(3002)).toMatchObject({ code: 'ADMITTED', machineId: 2 });
        expect(byReq.get(3003)).toMatchObject({ code: 'MACHINE_PIN', machineId: 1 });
    });

    it('names no machine when the claims cannot say who leads', () => {
        expect(leadMachineOf(90, { liveClaims: [], ownClaimId: 9, ownMachineId: 1, role: 'subscriber' }))
            .toBeNull();
        expect(leadMachineOf(90, { liveClaims: [], ownClaimId: 9, ownMachineId: 1, role: 'lead' })).toBe(1);
    });
});

describe('a derived block, with the engine off → the predicted badges', () => {
    it('predicts what the engine published on the same inputs\' first cycle (A16)', () => {
        const predicted = predictedOverlayOf('A16', 0);
        const engine = engineOverlayOf('A16', 0);
        expect(predicted.source).toBe(SOURCE_PREDICTED);
        expect([...predicted.badges.values()].map((b) => [b.epicId, b.text, b.code, b.cutBefore]))
            .toEqual([...engine.badges.values()].map((b) => [b.epicId, b.text, b.code, b.cutBefore]));
        expect(predicted.cut).toBe(engine.cut);
        expect(predicted.limits).toEqual(engine.limits);
        // Nothing to wait on: a prediction carries no executor outcome.
        expect(predicted.queue.every((q) => q.outcome === null)).toBe(true);
    });

    it('matches the fixture\'s prediction for every action state', () => {
        for (const a of fixture.actions) {
            a.states.forEach((state, i) => {
                const overlay = predictedOverlayOf(a.action, i);
                expect(overlay.queue.map((q) => [q.requirementId, q.code]))
                    .toEqual(state.predicted.queue.map((q) => [q.requirement_id, q.code]));
                expect(overlay.cut).toBe(state.predicted.cut);
            });
        }
    });
});

describe('the prediction\'s inputs', () => {
    const machine = { id: 1, max_live_sessions: 4 };
    it('counts this machine\'s live sessions against its ceiling', () => {
        const sessions = [
            { machine_fk: 1, swarm_status: 'active' }, { machine_fk: 1, swarm_status: 'review' },
            { machine_fk: 1, swarm_status: 'completed' }, { machine_fk: 1, swarm_status: 'paused' },
            { machine_fk: 2, swarm_status: 'active' },
        ];
        expect(predictionCapacity({ machine, sessions, inFlightElsewhere: [7, 7, 8] }))
            .toEqual({ ceiling: 4, live: 2, reserved_elsewhere: 2 });
    });

    it('leaves what it cannot read unknown, so the prediction says CAPACITY-UNKNOWN', () => {
        expect(predictionCapacity({ machine, sessions: [], sessionsKnown: false }).live).toBeNull();
        expect(predictionCapacity({ machine: { id: 1 }, sessions: [] }).ceiling).toBeNull();
        expect(predictionCapacity({ machine: null, sessions: [] }))
            .toEqual({ ceiling: null, live: null, reserved_elsewhere: 0 });
    });

    it('adds the claim this engine would take, after every holder', () => {
        const claims = predictionClaims({ claimRows: [{ id: 4, pipeline_fk: 9, machine_fk: 2 }],
            pipelineId: 9, machineId: 1 });
        expect(claims.own).toMatchObject({ claim_id: 5, machine_fk: 1, pipeline_id: 9, initiative_id: null });
        expect(claims.live.map((c) => c.id)).toEqual([4, 5]);
        expect(claims.proven).toBe(true);
        expect(predictionClaims({ claimRows: [], pipelineId: 9, machineId: 1 }).own.claim_id).toBe(1);
    });
});
